def fetch_category_totals(rows):
    """按类目汇总数量的示例实现（具名函数，合成编写）。"""
    totals = {}
    for row in rows:
        category = row.get("category", "未分类")
        totals[category] = totals.get(category, 0) + 1
    return dict(sorted(totals.items()))

